    out = [row[:] for row in grid]
    tracks = {}

    # Find gaps in horizontal bars that are bounded by the same color.
    for r, row in enumerate(grid):
        for c in range(1, w - 1):
            if row[c] != 0:
                continue
            left = next((row[k] for k in range(c - 1, -1, -1) if row[k] != 0), 0)
            right = next((row[k] for k in range(c + 1, w) if row[k] != 0), 0)
            if left and left == right:
                tracks.setdefault(c, []).append((r, left))

    for c, events in tracks.items():
        events.sort()
        start = 0
        for r, color in events:
            for rr in range(start, r + 1):
                out[rr][c] = color
            start = r + 1

        # Continue the vertical stem below the lowest horizontal crossing.
        last_r = events[-1][0]
        bottom_color = next(
            (grid[rr][c] for rr in range(h - 1, last_r, -1) if grid[rr][c] != 0),
            0
        )
        if bottom_color:
            for rr in range(last_r + 1, h):
                out[rr][c] = bottom_color

    return out
